int replace_net_table(struct net *net, const void __user *user, unsigned int len) {
    void *tmp = NULL;
    int ret = -ENOMEM;
    size_t entry_size;
    size_t num_entries;

    if (!net || !user || !len) {
        return -EINVAL;
    }

    if (len % sizeof(entry_size)) {
        return -EINVAL;
    }

    tmp = kmalloc(len, GFP_KERNEL);
    if (!tmp) {
        return -ENOMEM;
    }

    if (copy_from_user(tmp, user, len)) {
        kfree(tmp);
        return -EFAULT;
    }

    num_entries = len / sizeof(entry_size);
    if (num_entries == 0) {
        kfree(tmp);
        return -EINVAL;
    }

    if (num_entries > (SIZE_MAX / sizeof(entry_size))) {
        kfree(tmp);
        return -EOVERFLOW;
    }

    ret = finish_replace_net_table(net, tmp, num_entries);
    if (ret < 0) {
        kfree(tmp);
        return ret;
    }

    return 0;
}
